/* SWA Study Guide behaviour - generated by the generate-study-guide skill.
   Edit .github/skills/generate-study-guide/assets/app.js, not the copy in
   SWA-Study-Guide/. Runs from file:// with no network access. */
(() => {
  'use strict';

  const root = document.documentElement;
  const page = document.body.dataset;
  const base = page.base || '';
  const STORE = { theme: 'swa-guide-theme', read: 'swa-guide-read', nav: 'swa-guide-nav' };

  const read = key => { try { return JSON.parse(localStorage.getItem(key)) || null; } catch { return null; } };
  const write = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* private mode */ } };

  const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---------- theme ---------- */

  const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
  const applyTheme = theme => {
    root.dataset.theme = theme;
    const button = document.querySelector('[data-action="theme"]');
    if (button) {
      button.setAttribute('aria-label', `Switch to ${theme === 'dark' ? 'light' : 'dark'} theme`);
      button.textContent = theme === 'dark' ? '☀' : '☾';
    }
  };
  applyTheme(read(STORE.theme) || (prefersDark.matches ? 'dark' : 'light'));
  prefersDark.addEventListener('change', event => {
    if (!read(STORE.theme)) applyTheme(event.matches ? 'dark' : 'light');
  });

  /* ---------- read progress per topic ---------- */

  const readTopics = new Set(read(STORE.read) || []);
  const persistRead = () => write(STORE.read, [...readTopics]);

  const paintReadState = () => {
    document.querySelectorAll('[data-topic-id]').forEach(element => {
      element.classList.toggle('is-read', readTopics.has(element.dataset.topicId));
    });
    document.querySelectorAll('[data-chapter-meter]').forEach(meter => {
      const ids = (meter.dataset.topicIds || '').split(' ').filter(Boolean);
      const done = ids.filter(id => readTopics.has(id)).length;
      const fill = meter.querySelector('.meter__fill');
      const label = meter.querySelector('.meter__label');
      if (fill) fill.style.width = ids.length ? `${(done / ids.length) * 100}%` : '0';
      if (label) label.textContent = `${done} of ${ids.length} topics read`;
    });
    const overall = document.querySelector('[data-overall-progress]');
    if (overall) {
      const total = Number(overall.dataset.total || 0);
      overall.textContent = total ? `${Math.round((readTopics.size / total) * 100)}%` : '0%';
    }
  };

  const toggle = document.querySelector('[data-action="mark-read"]');
  if (toggle) {
    const id = toggle.dataset.topicId;
    const sync = () => {
      const done = readTopics.has(id);
      toggle.setAttribute('aria-pressed', String(done));
      toggle.querySelector('[data-label]').textContent = done ? 'Marked as read' : 'Mark as read';
    };
    toggle.addEventListener('click', () => {
      if (readTopics.has(id)) readTopics.delete(id); else readTopics.add(id);
      persistRead(); sync(); paintReadState();
    });
    sync();
  }
  paintReadState();

  /* ---------- sidebar ---------- */

  const navToggle = document.querySelector('[data-action="nav"]');
  if (navToggle) {
    navToggle.addEventListener('click', () => {
      const open = document.body.dataset.sidebar === 'open';
      document.body.dataset.sidebar = open ? 'closed' : 'open';
      navToggle.setAttribute('aria-expanded', String(!open));
    });
  }
  document.querySelectorAll('.nav-chapter').forEach(details => {
    const state = read(STORE.nav) || {};
    if (details.dataset.chapter in state) details.open = state[details.dataset.chapter];
    details.addEventListener('toggle', () => {
      const next = read(STORE.nav) || {};
      next[details.dataset.chapter] = details.open;
      write(STORE.nav, next);
    });
  });
  const current = document.querySelector('.nav-list a[aria-current="page"]');
  if (current) current.scrollIntoView({ block: 'center' });

  /* ---------- reading progress bar ---------- */

  const bar = document.querySelector('.progress-bar');
  if (bar) {
    const update = () => {
      const max = document.documentElement.scrollHeight - window.innerHeight;
      bar.style.width = `${max > 0 ? Math.min(100, (window.scrollY / max) * 100) : 0}%`;
    };
    window.addEventListener('scroll', update, { passive: true });
    window.addEventListener('resize', update);
    update();
  }

  /* ---------- on this page ---------- */

  const tocLinks = [...document.querySelectorAll('.toc a')];
  if (tocLinks.length) {
    const targets = tocLinks
      .map(link => document.getElementById(decodeURIComponent(link.hash.slice(1))))
      .filter(Boolean);
    const spy = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        tocLinks.forEach(link => link.classList.toggle('is-active', link.hash.slice(1) === entry.target.id));
      });
    }, { rootMargin: '-80px 0px -70% 0px', threshold: 0 });
    targets.forEach(target => spy.observe(target));
  }

  /* ---------- scroll-reveal for .fade-in elements ---------- */

  if (!prefersReduced) {
    const reveals = document.querySelectorAll('.fade-in');
    if (reveals.length) {
      reveals.forEach(el => { el.style.animationPlayState = 'paused'; });
      const observer = new IntersectionObserver(entries => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            entry.target.style.animationPlayState = 'running';
            observer.unobserve(entry.target);
          }
        });
      }, { rootMargin: '0px 0px -60px 0px', threshold: 0.05 });
      reveals.forEach(el => observer.observe(el));
    }
  }

  /* ---------- animated stat counters ---------- */

  const statValues = document.querySelectorAll('.stat__value[data-target]');
  if (statValues.length && !prefersReduced) {
    const animateCounter = el => {
      const target = parseInt(el.dataset.target, 10);
      if (isNaN(target)) return;
      const suffix = el.dataset.suffix || '';
      const duration = 1400;
      let start = null;
      const step = ts => {
        if (!start) start = ts;
        const progress = Math.min((ts - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        el.textContent = Math.round(eased * target).toLocaleString() + suffix;
        if (progress < 1) requestAnimationFrame(step);
      };
      el.textContent = '0' + suffix;
      requestAnimationFrame(step);
    };
    const statObserver = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          animateCounter(entry.target);
          statObserver.unobserve(entry.target);
        }
      });
    }, { threshold: 0.3 });
    statValues.forEach(el => statObserver.observe(el));
  }

  /* ---------- image lightbox ---------- */

  const lightbox = document.querySelector('.lightbox');
  if (lightbox) {
    const frame = lightbox.querySelector('img');
    const openLightbox = () => lightbox.classList.add('is-open');
    const closeLightbox = () => { lightbox.classList.remove('is-open'); frame.removeAttribute('src'); };
    document.querySelectorAll('.prose img').forEach(image => {
      image.addEventListener('click', () => {
        frame.src = image.currentSrc || image.src;
        frame.alt = image.alt;
        openLightbox();
      });
    });
    lightbox.addEventListener('click', closeLightbox);
  }

  /* ---------- search palette ---------- */

  const palette = document.querySelector('.palette');
  const index = window.SWA_SEARCH_INDEX || [];
  if (palette && index.length) {
    const input = palette.querySelector('.palette__input');
    const results = palette.querySelector('.palette__results');
    const empty = palette.querySelector('.palette__empty');
    let selected = 0;

    const escapeHtml = text => text.replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
    const highlight = (text, terms) => terms.reduce(
      (out, term) => out.replace(new RegExp(`(${term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'ig'), '<mark>$1</mark>'),
      escapeHtml(text)
    );

    const score = (entry, terms) => {
      let total = 0;
      for (const term of terms) {
        const inTitle = entry.title.toLowerCase().includes(term);
        const inHeadings = entry.headings.some(heading => heading.toLowerCase().includes(term));
        const hits = entry.lower.split(term).length - 1;
        if (!inTitle && !inHeadings && !hits) return 0;
        total += (inTitle ? 60 : 0) + (inHeadings ? 20 : 0) + Math.min(hits, 12);
      }
      return total;
    };

    const snippet = (entry, term) => {
      const at = entry.lower.indexOf(term);
      if (at === -1) return entry.text.slice(0, 160);
      return `${at > 40 ? '…' : ''}${entry.text.slice(Math.max(0, at - 40), at + 140)}…`;
    };

    const render = query => {
      const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
      results.innerHTML = '';
      selected = 0;
      if (!terms.length) { empty.textContent = 'Type to search all topics.'; empty.hidden = false; return; }

      const matches = index
        .map(entry => ({ entry, rank: score(entry, terms) }))
        .filter(item => item.rank > 0)
        .sort((left, right) => right.rank - left.rank)
        .slice(0, 25);

      if (!matches.length) { empty.textContent = `No topic matches “${query}”.`; empty.hidden = false; return; }
      empty.hidden = true;
      results.innerHTML = matches.map(({ entry }, position) => `
        <li role="option" aria-selected="${position === 0}">
          <a href="${base}${entry.url}">
            <span class="palette__chapter">${escapeHtml(entry.chapter)}</span>
            <strong>${highlight(entry.title, terms)}</strong>
            <span class="palette__snippet">${highlight(snippet(entry, terms[0]), terms)}</span>
          </a>
        </li>`).join('');
    };

    const move = step => {
      const items = [...results.children];
      if (!items.length) return;
      items[selected]?.setAttribute('aria-selected', 'false');
      selected = (selected + step + items.length) % items.length;
      const item = items[selected];
      item.setAttribute('aria-selected', 'true');
      item.scrollIntoView({ block: 'nearest' });
    };

    const open = () => { palette.classList.add('is-open'); input.value = ''; render(''); input.focus(); };
    const close = () => { palette.classList.remove('is-open'); };

    document.querySelectorAll('[data-action="search"]').forEach(button => button.addEventListener('click', open));
    input.addEventListener('input', () => render(input.value));
    palette.addEventListener('click', event => { if (event.target === palette) close(); });
    palette.addEventListener('keydown', event => {
      if (event.key === 'Escape') { close(); return; }
      if (event.key === 'ArrowDown') { event.preventDefault(); move(1); }
      if (event.key === 'ArrowUp') { event.preventDefault(); move(-1); }
      if (event.key === 'Enter') {
        const link = results.children[selected]?.querySelector('a');
        if (link) { event.preventDefault(); window.location.href = link.getAttribute('href'); }
      }
    });

    document.addEventListener('keydown', event => {
      const typing = /^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName);
      if ((event.key === 'k' && (event.ctrlKey || event.metaKey)) || (event.key === '/' && !typing)) {
        event.preventDefault();
        if (!palette.classList.contains('is-open')) open(); else close();
      }
    });
  }

  /* ---------- keyboard paging ---------- */

  document.addEventListener('keydown', event => {
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    if (/^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName)) return;
    if (palette && palette.classList.contains('is-open')) return;
    const link = event.key === 'ArrowLeft' ? document.querySelector('.pager__prev')
      : event.key === 'ArrowRight' ? document.querySelector('.pager__next') : null;
    if (link) window.location.href = link.getAttribute('href');
  });

  /* ---------- theme button ---------- */

  document.querySelectorAll('[data-action="theme"]').forEach(button => button.addEventListener('click', () => {
    const next = root.dataset.theme === 'dark' ? 'light' : 'dark';
    write(STORE.theme, next);
    applyTheme(next);
    if (window.mermaid) window.location.reload();
  }));

  /* ---------- mermaid ---------- */

  if (window.mermaid && document.querySelector('.mermaid')) {
    window.mermaid.initialize({
      startOnLoad: true,
      securityLevel: 'loose',
      theme: root.dataset.theme === 'dark' ? 'dark' : 'neutral',
      fontFamily: getComputedStyle(document.body).fontFamily,
    });
  }
})();
